def isIsomorphic(self, s: str, t: str) -> bool:
    if len(s) != len(t):
        return False
    last_s: dict[str, int] = {}
    last_t: dict[str, int] = {}
    for i, (a, b) in enumerate(zip(s, t)):
        if last_s.get(a, 0) != last_t.get(b, 0):
            return False
        last_s[a] = i + 1
        last_t[b] = i + 1
    return True

